-- GENERATED by scripts/supabase-migrations.sh from supabase/schema-competitions.sql — edit that file, then regenerate.

-- ============================================================
-- Quantum Lab — weekly gate-golf competition schema
--
-- Run this in the Supabase SQL editor AFTER schema.sql. As with the
-- exams schema, the app boots without it: with no
-- SUPABASE_SERVICE_ROLE_KEY the compete store falls back to a Map in
-- the Node process (apps/web/lib/compete/store.ts) and the page says
-- the leaderboard is not durable. For a deployment, run this file.
--
-- ############################################################
-- #  THESE TABLES ARE WRITTEN ONLY BY THE SERVICE ROLE.      #
-- #                                                          #
-- #  A leaderboard row IS the score. The server re-runs the  #
-- #  submitted QASM through the real grader and recomputes   #
-- #  the gate count itself before writing (lib/compete/      #
-- #  engine.ts); a client that could INSERT or UPDATE here   #
-- #  could write best_gates = 1 and own every week. So RLS   #
-- #  is enabled and NO table policy is created: with RLS on  #
-- #  and no policy, anon and authenticated can do nothing,   #
-- #  and the service role — which bypasses RLS — is the only #
-- #  path in.                                                #
-- #                                                          #
-- #  The PUBLIC read path is the view below, not the table.  #
-- #  The table carries account_id (a user id) and the full   #
-- #  submitted QASM; the view exposes display name, gate     #
-- #  count and time — the leaderboard, nothing else.         #
-- ############################################################
--
-- HONESTY NOTE, same as schema-exams.sql: this file has never been
-- run against a live Supabase project. The shapes match what
-- apps/web/lib/compete/store.ts reads and writes, and that mapping is
-- covered by tests against an in-memory double, but the SQL itself is
-- unverified. Check it before trusting it.
-- ============================================================

-- ── Competitions ─────────────────────────────────────────────
-- One row per ISO week, written lazily by the server the first time
-- anyone submits. The row is an AUDIT RECORD, not the authority: the
-- competition itself is derived deterministically from the ISO week
-- (lib/compete/engine.ts), so the app never needs an operator to
-- schedule one and never reads this table to decide what this week's
-- puzzle is. The row exists so that past weeks' parameters survive a
-- code change to the generator — without it, a tweak to the puzzle
-- derivation would silently rewrite history under old entries.
create table if not exists public.competitions (
  id            text primary key,          -- 'weekly-2026-W35'
  week_key      text not null,             -- '2026-W35' (ISO week)
  num_qubits    integer not null check (num_qubits between 1 and 8),
  par           integer not null check (par between 1 and 64),
  -- The target distribution, one probability per basis state. Stored
  -- as jsonb because its length is 2^num_qubits and the app treats it
  -- as an opaque array.
  target_probabilities jsonb not null,
  starts_at     timestamptz not null,      -- Monday 00:00 UTC
  ends_at       timestamptz not null,      -- next Monday 00:00 UTC
  check (ends_at > starts_at)
);

alter table public.competitions enable row level security;
-- No policies: service role only. The public may learn this week's
-- puzzle from GET /api/compete, which derives it rather than reading
-- this table.

-- ── Entries ──────────────────────────────────────────────────
-- One row per (competition, account): a player's BEST entry for the
-- week. The server only overwrites a row when the new submission's
-- recomputed gate count is strictly lower, so submitted_at is the
-- moment the standing score was achieved — ties on gate count rank
-- by who got there first.
create table if not exists public.competition_entries (
  competition_id text not null references public.competitions (id),
  account_id     text not null,            -- Supabase auth user id, from a verified token
  display_name   text not null check (char_length(display_name) between 1 and 40),
  best_gates     integer not null check (best_gates between 1 and 512),
  -- The OpenQASM that earned the score, kept so the score is
  -- re-checkable after the fact and so the player can reload their
  -- own best circuit. Never exposed through the view: a leader's
  -- circuit is the answer to a live puzzle.
  qasm           text not null check (char_length(qasm) <= 32768),
  submitted_at   timestamptz not null default now(),
  primary key (competition_id, account_id)
);

create index if not exists competition_entries_rank_idx
  on public.competition_entries (competition_id, best_gates, submitted_at);

alter table public.competition_entries enable row level security;
-- No policies: writes go through the service role, which grades first.

-- ── The public leaderboard view ──────────────────────────────
-- Join-safe by construction: it names the three columns a leaderboard
-- shows and nothing more. No account_id (a stable identifier someone
-- could correlate across features) and no qasm (the answer key for a
-- competition that is still running).
--
-- security_invoker = false is DELIBERATE here, and is the one place
-- in this project a view reads past RLS: the view runs with its
-- owner's rights, which is what lets anon read rows the table policy
-- denies. That is safe precisely because the column list is closed —
-- widening this view IS widening the security boundary, so treat any
-- edit to it as you would a policy change.
create or replace view public.competition_leaderboard
  with (security_invoker = false) as
  select competition_id, display_name, best_gates, submitted_at
  from public.competition_entries;

grant select on public.competition_leaderboard to anon, authenticated;
